-- 굿즈 same-price CPQ 7상품 UNDO
\set ON_ERROR_STOP on
BEGIN;
DELETE FROM t_prd_product_option_items WHERE prd_cd IN ('PRD_000188','PRD_000190','PRD_000192','PRD_000267','PRD_000208','PRD_000221','PRD_000242') AND opt_cd BETWEEN 'OPV_000752' AND 'OPV_000768';
