DELETE FROM t_prd_product_option_groups WHERE prd_cd IN ('PRD_000188','PRD_000190','PRD_000192','PRD_000267','PRD_000208','PRD_000221','PRD_000242') AND opt_grp_cd BETWEEN 'OPT_000205' AND 'OPT_000211';
DELETE FROM t_prd_product_sizes WHERE siz_cd IN ('SIZ_000614','SIZ_000615','SIZ_000616','SIZ_000617','SIZ_000618','SIZ_000619','SIZ_000620','SIZ_000621','SIZ_000622');
DELETE FROM t_siz_sizes WHERE siz_cd IN ('SIZ_000614','SIZ_000615','SIZ_000616','SIZ_000617','SIZ_000618','SIZ_000619','SIZ_000620','SIZ_000621','SIZ_000622');
